/**
 * Pure Pythagorean-hodograph maths on plain numbers (no Points, no caching).
 *
 * A PH Bezier curve of degree n = 2m - 1 is generated by m "hodograph points" w_0..w_(m-1), read as
 * complex numbers: its derivative is r'(t) = sum_k n * dP_k * B_k^(n-1)(t) with the control-point
 * differences dP given by the Bernstein-form product w(t)^2. All functions here take and return
 * [x, y] pairs.
 */
export type Vec = readonly [number, number];

export function binomial(n: number, k: number): number {
    return k === 0 ? 1 : (n * binomial(n - 1, k - 1)) / k;
}

/** Degree of the PH curve generated by m hodograph points. */
export function phDegree(m: number): number {
    return 2 * m - 1;
}

/**
 * Control points P_0..P_n of the PH curve starting at `start` with hodograph points `w`:
 * P_(k+1) = P_k + (1/n) * (complex Bernstein product of w with itself)_k.
 */
export function phControlPoints(start: Vec, w: ReadonlyArray<Vec>): Vec[] {
    const m = w.length;
    const n = phDegree(m);
    const points: Vec[] = [start];
    for (let k = 0; k < n; k++) {
        let sumX = 0;
        let sumY = 0;
        const end = Math.min(k, m - 1);
        for (let j = Math.max(0, k - m + 1); j <= end; j++) {
            const scalar = binomial(m - 1, j) / binomial(2 * m - 2, k) * binomial(m - 1, k - j);
            const [ax, ay] = w[j];
            const [bx, by] = w[k - j];
            sumX = scalar * (ax * bx - ay * by) + sumX;
            sumY = scalar * (ax * by + ay * bx) + sumY;
        }
        points.push([points[k][0] + 1 / n * sumX, points[k][1] + 1 / n * sumY]);
    }
    return points;
}

/**
 * Bernstein coefficients sigma_0..sigma_(n-1) of the parametric speed |r'(t)| (a degree n-1
 * polynomial, because |w(t)|^2 is).
 */
export function phSigmas(w: ReadonlyArray<Vec>): number[] {
    const n = phDegree(w.length);
    const m = (n - 1) / 2;
    const sigmas: number[] = [];
    for (let k = 0; k < n; k++) {
        let sum = 0;
        const end = Math.min(m, k);
        for (let j = Math.max(0, k - m); j <= end; j++) {
            const scalar = binomial(m, j) / binomial(n - 1, k) * binomial(m, k - j);
            sum = scalar * (w[j][0] * w[k - j][0] + w[j][1] * w[k - j][1]) + sum;
        }
        sigmas.push(sum);
    }
    return sigmas;
}

/**
 * The offset curve at signed distance `d` of a PH curve is rational of degree 2n - 1; returns its
 * 2n control points and weights, from the PH control points `p` and speed coefficients `sigmas`.
 */
export function phOffsetRational(p: ReadonlyArray<Vec>, sigmas: ReadonlyArray<number>, d: number): { points: Vec[], weights: number[] } {
    const n = p.length - 1;
    // Edge normals (rotated differences) of the control polygon.
    const normals: Vec[] = p.slice(1).map((q, i) => [q[1] - p[i][1], p[i][0] - q[0]]);
    const points: Vec[] = [];
    const weights: number[] = [];
    for (let k = 0; k < 2 * n; k++) {
        let sumX = 0;
        let sumY = 0;
        let sumW = 0;
        const end = Math.min(n - 1, k);
        for (let j = Math.max(0, k - n); j <= end; j++) {
            const scalar = binomial(n - 1, j) / binomial(2 * n - 1, k) * binomial(n, k - j);
            sumX = scalar * (sigmas[j] * p[k - j][0] + d * n * normals[j][0]) + sumX;
            sumY = scalar * (sigmas[j] * p[k - j][1] + d * n * normals[j][1]) + sumY;
            sumW = scalar * sigmas[j] + sumW;
        }
        weights.push(sumW);
        points.push([sumX / sumW, sumY / sumW]);
    }
    return {points, weights};
}
